/*
 * A232563  Sequence (or tree) generated by these rules: 1 is in S, and if x
 *          is in S, then x + 1 and 4*x are in S, and duplicates are deleted
 *          as they occur.
 * https://oeis.org/A232563
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 27, u16 n <= 399, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  Sequence A232563
 *  Generation rule: 1 is in S; for each x∈S, x+1 and 4*x are inserted
 *  as children of x, unless they already appeared earlier.  The order
 *  of S is the order in which the children are produced during a
 *  breadth‑first traversal, so a(n) is the (n‑th) element of this list.
 *
 *  The implementation builds the sequence incrementally, caching all
 *  previously computed elements.  Each new child is checked against
 *  the cache by a linear scan; this suffices for n≤10 000.  Subsequent
 *  calls use the cached data, so the function works for arbitrary order
 *  of requests.  All arithmetic is performed in seq_t; the constants
 *  are cast appropriately. */

#include <stddef.h>
#include <stdlib.h>
#include <stdbool.h>

seq_t a(idx_t n)
{
    /* Static state shared by all calls */
    static seq_t *seq = NULL;   /* cache of generated numbers */
    static size_t  cap = 0;     /* current allocation size          */
    static idx_t   len = 0;     /* number of elements stored so far  */
    static idx_t   proc = 0;    /* index of next parent to process   */

    /* Initialisation on first call */
    if (len == 0) {
        cap = 64;
        seq = (seq_t *)malloc(cap * sizeof(seq_t));
        if (!seq) abort();
        seq[0] = (seq_t)1;
        len  = 1;
        proc = 0;
    }

    /* Grow the cache as needed */
    if (n > cap) {
        while (cap < n) cap <<= 1;
        seq = (seq_t *)realloc(seq, cap * sizeof(seq_t));
        if (!seq) abort();
    }

    /* Generate new elements until we have at least n of them */
    while (len < n) {
        /* Process the next parent in the breadth‑first queue */
        seq_t x = seq[proc++];

        /* Child 1: x + 1 */
        seq_t c1 = x + (seq_t)1;
        bool seen = false;
        for (size_t i = 0; i < (size_t)len; ++i) {
            if (seq[i] == c1) { seen = true; break; }
        }
        if (!seen) {
            if (len == cap) {
                cap <<= 1;
                seq = (seq_t *)realloc(seq, cap * sizeof(seq_t));
                if (!seq) abort();
            }
            seq[len++] = c1;
        }

        /* Child 2: 4 * x */
        seq_t c2 = x * (seq_t)4;
        seen = false;
        for (size_t i = 0; i < (size_t)len; ++i) {
            if (seq[i] == c2) { seen = true; break; }
        }
        if (!seen) {
            if (len == cap) {
                cap <<= 1;
                seq = (seq_t *)realloc(seq, cap * sizeof(seq_t));
                if (!seq) abort();
            }
            seq[len++] = c2;
        }
    }

    return seq[n - 1];
}
